<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import PageHeader from '../components/PageHeader.vue';import StatusPanel from '../components/StatusPanel.vue';import { api,queryString } from '../lib/api';
const loading=ref(true),error=ref(''),data=ref({}),filters=reactive({period:'monthly',device_type:'',date_field:'created_at'});const overview=computed(()=>data.value.overview||{}),content=computed(()=>data.value.content||{});
const cards=computed(()=>[['Active users',overview.value.total_active_users,'Live customer accounts'],['Subscribers',overview.value.total_users_with_active_subscription,'Users with active access'],['Subscriptions',overview.value.total_active_subscriptions,'Across every device type'],['Movies',overview.value.total_movies??content.value.total_movies,'Published catalog titles'],['Seasons',overview.value.total_seasons??content.value.total_seasons,'Series collections'],['Episodes',overview.value.total_episodes??content.value.total_episodes,'Available episodes']]);
const number=(v)=>new Intl.NumberFormat('en-IN').format(Number(v||0)),money=(v)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(v||0));
async function load(){loading.value=true;error.value='';try{const r=await api(`/admin/dashboard${queryString(filters)}`);const legacy=r?.data||r;data.value=legacy?.data||legacy||{}}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(load);
</script>
<template><div class="admin-page"><PageHeader eyebrow="Control room" title="Dashboard" description="A live view of Zo Stream's audience, revenue and content library."><button class="admin-secondary" @click="load">Refresh</button></PageHeader><section class="admin-filter-bar"><label>Period<select v-model="filters.period" @change="load"><option>daily</option><option>monthly</option><option>yearly</option></select></label><label>Device<select v-model="filters.device_type" @change="load"><option value="">All devices</option><option>mobile</option><option>browser</option><option>tv</option></select></label><label>Date field<select v-model="filters.date_field" @change="load"><option value="created_at">Created</option><option value="start_at">Start</option><option value="end_at">End</option></select></label></section><StatusPanel tone="error" :message="error"/><div v-if="loading" class="admin-loading">Loading dashboard…</div><template v-else><section class="admin-stat-grid"><article v-for="(card,i) in cards" :key="card[0]" :style="`--card-index:${i}`"><p>{{card[0]}}</p><strong>{{number(card[1])}}</strong><span>{{card[2]}}</span></article></section><section class="admin-dashboard-grid"><article class="admin-panel"><header><div><p>SUBSCRIPTION MIX</p><h2>Performance by plan</h2></div><strong>{{money(data.plan_amount_summary?.total_amount)}}</strong></header><div class="admin-plan-list"><div v-for="plan in data.active_subscriptions_by_plan||[]" :key="plan.plan_id"><span><b>{{plan.plan_name||'Unnamed plan'}}</b><small>{{plan.device_type}} · {{plan.duration_days}} days</small></span><i><b>{{number(plan.total_active_subscriptions)}}</b><small>{{money(plan.total_amount)}}</small></i></div></div></article><article class="admin-panel"><header><div><p>DEVICE REACH</p><h2>Active subscriptions</h2></div></header><div class="admin-device-list"><div v-for="d in data.active_subscriptions_by_device||[]" :key="d.device_type"><span>{{d.device_type}}</span><strong>{{number(d.total_active_subscriptions)}}</strong><small>{{money(d.total_amount)}}</small></div></div></article></section></template></div></template>
